import { expect, expectStatus, test, type APIRequestContext } from "../../fixtures";

interface VendorBody {
  id: string;
  status: string;
}

interface DocumentBody {
  id: string;
  status: string;
}

interface ExtractionBody {
  id: string;
  status: string;
}

interface ReviewQueueBody {
  vendor_id: string;
  extractions: ExtractionBody[];
}

interface AuditBody {
  items: { action: string }[];
}

const DOCUMENT_KINDS = ["w9", "insurance_certificate", "contract"] as const;

test("approving every extraction approves the vendor", { tag: "@REV-05" }, async ({ apiAs }) => {
  // Arrange: a member creates a uniquely named vendor and uploads all three documents.
  const member = await apiAs("member");
  const reviewer = await apiAs("reviewer");
  const uniqueName = `Review Vendor ${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;

  const created = await expectStatus<VendorBody>(
    await member.post("/api/vendors", {
      data: { name: uniqueName, category: "services", contact_email: "ops@review-vendor.test" },
    }),
    201,
  );
  const vendorId = created.id;

  const documentIds: string[] = [];
  for (const kind of DOCUMENT_KINDS) {
    const doc = await expectStatus<DocumentBody>(
      await member.post(`/api/vendors/${vendorId}/documents`, {
        multipart: {
          kind,
          file: {
            name: `${kind}.pdf`,
            mimeType: "application/pdf",
            buffer: Buffer.from("%PDF-1.4 review test document"),
          },
        },
      }),
      201,
    );
    documentIds.push(doc.id);
  }

  // Wait until every document has been extracted before submitting.
  for (const documentId of documentIds) {
    await expect
      .poll(
        async () => {
          const body = await expectStatus<DocumentBody>(await member.get(`/api/documents/${documentId}`), 200);
          return body.status;
        },
        { timeout: 60_000 },
      )
      .toBe("extracted");
  }

  // Submit the vendor, moving it into review.
  const submitted = await expectStatus<VendorBody>(await member.post(`/api/vendors/${vendorId}/submit`), 200);
  expect(submitted.status).toBe("in_review");

  // Locate the three pending extractions for this vendor in the review queue.
  let extractions: ExtractionBody[] = [];
  await expect
    .poll(
      async () => {
        const queue = await expectStatus<ReviewQueueBody[]>(await reviewer.get("/api/review-queue"), 200);
        const item = queue.find((entry) => entry.vendor_id === vendorId);
        extractions = item?.extractions ?? [];
        return extractions.length;
      },
      { timeout: 60_000 },
    )
    .toBe(3);

  for (const extraction of extractions) {
    expect(extraction.status).toBe("pending_review");
  }

  // Act: the reviewer approves every extraction.
  for (const extraction of extractions) {
    const decided = await expectStatus<ExtractionBody>(
      await reviewer.post(`/api/extractions/${extraction.id}/decision`, {
        data: { decision: "approve" },
      }),
      200,
    );
    expect(decided.status).toBe("approved");
  }

  // Assert: the vendor is approved.
  const vendor = await expectStatus<VendorBody>(await reviewer.get(`/api/vendors/${vendorId}`), 200);
  expect(vendor.status).toBe("approved");

  // Assert: an audit event "vendor.approved" is recorded for this vendor.
  const audit = await expectStatus<AuditBody>(await reviewer.get(`/api/vendors/${vendorId}/audit`), 200);
  const approvedEvents = audit.items.filter((event) => event.action === "vendor.approved");
  expect(approvedEvents.length).toBeGreaterThanOrEqual(1);
});
